  const size_t memory=32*sizeof(Header)+256+128*sizeof(uint32_t);
  WriterChannel output("pinReply",memory,32,128);
  ReaderChannel input("pinForward",memory,32,128);
  WriterChannel peer("pinForward",memory,32,128);Device::install(&output,&input);
  std::array<uint8_t,64> payload{};payload.fill(0x4d);
