  Device::pinRead(7);void* pointer=nullptr;Device::get_data(&pointer);Device::end_read_data();
  const auto pinned=input.control->consumed.load();require(pinned==1,"pin earliest live payload");
  append();require(Device::waitForCommand()==Result::Success,"pin second wait");Device::pop_front();Device::get_data();
  void* later=nullptr;Device::get_data(&later);Device::end_read_data();
  require(input.control->consumed.load()==pinned,"later packet released pinned memory");
  require(static_cast<uint8_t*>(pointer)[63]==0x4d,"live pinned pointer integrity");
  append();require(Device::waitForCommand()==Result::Success,"pin release wait");Device::pop_front();Device::get_data();Device::get_data(&later);
  Device::unpinRead(7);Device::end_read_data();require(input.control->consumed.load()==input.data->cursor(),"unpin failed to release");
  append();require(Device::waitForCommand()==Result::Success,"destroy pin wait");Device::pop_front();Device::get_data();Device::pinRead(9);Device::get_data(&later);
  Device::destroyReadPins(9);Device::end_read_data();require(input.control->consumed.load()==input.data->cursor(),"destroy failed to release pin");
